'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),crypto=require('node:crypto');
test('every named diagram has a distinct, sharp local illustration',()=>{const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','diagrams-art.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const entries=c.window.PHOENIX_DIAGRAMS.entries,art=c.window.PHOENIX_DIAGRAM_ART;assert.equal(Object.keys(art).length,entries.length);assert.equal(new Set(entries.map(e=>art[e.id]?.src)).size,entries.length);assert.equal(new Set(entries.map(e=>art[e.id]?.sha256)).size,entries.length);for(const e of entries){const a=art[e.id];assert.ok(a,e.id);assert.ok(a.originalSize.every(n=>n>=800)&&a.originalSize[0]*a.originalSize[1]>=1400000,e.id);const bytes=fs.readFileSync(a.src);assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),a.sha256,e.id);}});
